        TMAX_PRORL_GIT_COMMIT TMAX_SLIME_GIT_COMMIT TMAX_MEGATRON_GIT_COMMIT
        HF_CHECKPOINT REF_LOAD TORCH_DIST_DIR MODEL_ARGS_FILE
        ACCOUNT PARTITION SLURM_CONSTRAINT SLURM_EXCLUDE NUM_NODES SLURM_GPUS
