        POLAR_GATEWAY_COMPLETION_QUEUE_SIZE
        POLAR_GATEWAY_COMPLETION_WRITE_WORKERS
        POLAR_COMPLETION_BATCH_SIZE POLAR_COMPLETION_WRITE_MAX_ATTEMPTS
